import{_ as e,o as t,c as o,ae as r}from"./chunks/framework.Dh1jimFm.js";const h=JSON.parse('{"title":"Trados Studio Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"cat-tools/trados.md","filePath":"cat-tools/trados.md"}'),s={name:"cat-tools/trados.md"};function l(i,a,n,d,p,c){return t(),o("div",null,a[0]||(a[0]=[r(`<h1 id="trados-studio-workflow" tabindex="-1">Trados Studio Workflow <a class="header-anchor" href="#trados-studio-workflow" aria-label="Permalink to &quot;Trados Studio Workflow&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Using Supervertaler for Trados (plugin)?</strong> For documentation on the Trados Studio plugin (TermLens, AI Assistant, Batch Translate), see <a href="https://supervertaler.gitbook.io/trados" target="_blank" rel="noreferrer">Supervertaler for Trados</a>. This page covers the SDLPPX round-trip workflow using Supervertaler as a <strong>standalone application</strong>.</p></div><p>This guide covers working with Trados Studio packages in Supervertaler.</p><h2 id="recommended-sdlppx-packages" tabindex="-1">Recommended: SDLPPX Packages <a class="header-anchor" href="#recommended-sdlppx-packages" aria-label="Permalink to &quot;Recommended: SDLPPX Packages&quot;">​</a></h2><p>The best way to work with Trados Studio is using <strong>project packages</strong> (SDLPPX files).</p><h3 id="export-from-trados" tabindex="-1">Export from Trados <a class="header-anchor" href="#export-from-trados" aria-label="Permalink to &quot;Export from Trados&quot;">​</a></h3><ol><li>In Trados Studio, open your project</li><li>Go to <strong>Project</strong> → <strong>Package</strong> → <strong>Create Project Package</strong></li><li>Configure package options (include all files)</li><li>Save as <code>.sdlppx</code> file</li></ol><h3 id="import-to-supervertaler" tabindex="-1">Import to Supervertaler <a class="header-anchor" href="#import-to-supervertaler" aria-label="Permalink to &quot;Import to Supervertaler&quot;">​</a></h3><ol><li>Go to <strong>File → Import → Trados Package (SDLPPX)...</strong></li><li>Select your <code>.sdlppx</code> file</li><li>Supervertaler extracts and loads all segments</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>Tip</strong>: Package paths are saved in your <code>.svproj</code> file, so you can re-export to the same package later.</p></div><h2 id="translate-in-supervertaler" tabindex="-1">Translate in Supervertaler <a class="header-anchor" href="#translate-in-supervertaler" aria-label="Permalink to &quot;Translate in Supervertaler&quot;">​</a></h2><ol><li>Navigate through segments</li><li>Use AI translation (<code>Ctrl+T</code>) or translate manually</li><li>Confirm each segment (<code>Ctrl+Enter</code>)</li><li>Tags appear as <code>&lt;1&gt;</code>, <code>&lt;/1&gt;</code> - keep them in your translation</li></ol><h3 id="trados-tag-format" tabindex="-1">Trados Tag Format <a class="header-anchor" href="#trados-tag-format" aria-label="Permalink to &quot;Trados Tag Format&quot;">​</a></h3><p>Trados uses numbered XML-style tags:</p><table tabindex="0"><thead><tr><th>Tag</th><th>Purpose</th></tr></thead><tbody><tr><td><code>&lt;1&gt;</code></td><td>Opening tag</td></tr><tr><td><code>&lt;/1&gt;</code></td><td>Closing tag</td></tr><tr><td><code>&lt;2/&gt;</code></td><td>Standalone/empty tag</td></tr></tbody></table><p>These are highlighted in the grid for visibility.</p><h2 id="export-as-return-package" tabindex="-1">Export as Return Package <a class="header-anchor" href="#export-as-return-package" aria-label="Permalink to &quot;Export as Return Package&quot;">​</a></h2><ol><li>Go to <strong>File → Export → Trados Return Package (SDLRPX)...</strong></li><li>The return package is created with your translations</li><li>Segment status is updated to &quot;Translated&quot;</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The SDLRPX is created from your original SDLPPX with translations inserted.</p></div><h2 id="import-back-to-trados" tabindex="-1">Import Back to Trados <a class="header-anchor" href="#import-back-to-trados" aria-label="Permalink to &quot;Import Back to Trados&quot;">​</a></h2><ol><li>In Trados Studio, go to <strong>File</strong> → <strong>Open Package</strong></li><li>Select the <code>.sdlrpx</code> file from Supervertaler</li><li>Trados imports the return package</li><li>Your translations appear in the target segments</li></ol><hr><h2 id="alternative-bilingual-review-docx" tabindex="-1">Alternative: Bilingual Review DOCX <a class="header-anchor" href="#alternative-bilingual-review-docx" aria-label="Permalink to &quot;Alternative: Bilingual Review DOCX&quot;">​</a></h2><p>⚠️ <strong>Use SDLPPX instead if possible.</strong> The Bilingual Review format has limitations.</p><h3 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h3><p>Trados Bilingual Review DOCX is designed for <strong>review only</strong>, not translation:</p><ul><li>Empty target segments are not exported</li><li>You cannot translate from scratch using this format</li></ul><h3 id="workaround-if-you-must-use-it" tabindex="-1">Workaround (if you must use it) <a class="header-anchor" href="#workaround-if-you-must-use-it" aria-label="Permalink to &quot;Workaround (if you must use it)&quot;">​</a></h3><ol><li><strong>In Trados</strong>: Copy all source to target first <ul><li>Edit → Task → Copy source to target (batch task)</li></ul></li><li><strong>Export</strong>: File → Export → For Bilingual Review</li><li><strong>In Word</strong>: Delete all target text (cells remain, but empty)</li><li><strong>Import to Supervertaler</strong>: File → Import → Trados Bilingual DOCX</li><li><strong>Translate</strong> and export</li><li><strong>Re-import to Trados</strong>: Merge into project</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This workaround is tedious. Use SDLPPX packages whenever your client provides them.</p></div><hr><h2 id="complete-sdlppx-workflow" tabindex="-1">Complete SDLPPX Workflow <a class="header-anchor" href="#complete-sdlppx-workflow" aria-label="Permalink to &quot;Complete SDLPPX Workflow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trados: Create Project Package (.sdlppx)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>Supervertaler: Import Trados Package</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>Supervertaler: Translate (AI + manual)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>Supervertaler: Export Return Package (.sdlrpx)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>Trados: Open Return Package</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>Trados: QA + Delivery</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="cannot-find-sdlxliff-files" tabindex="-1">&quot;Cannot find SDLXLIFF files&quot; <a class="header-anchor" href="#cannot-find-sdlxliff-files" aria-label="Permalink to &quot;&quot;Cannot find SDLXLIFF files&quot;&quot;">​</a></h3><p>The SDLPPX might be corrupted or use an unsupported format.</p><ul><li>Try re-exporting from Trados Studio</li><li>Ensure all files are included in the package</li></ul><h3 id="status-shows-draft-instead-of-translated" tabindex="-1">Status shows &quot;Draft&quot; instead of &quot;Translated&quot; <a class="header-anchor" href="#status-shows-draft-instead-of-translated" aria-label="Permalink to &quot;Status shows &quot;Draft&quot; instead of &quot;Translated&quot;&quot;">​</a></h3><p>Fixed in v1.9.32. Update to the latest version.</p><h3 id="tags-not-matching" tabindex="-1">Tags not matching <a class="header-anchor" href="#tags-not-matching" aria-label="Permalink to &quot;Tags not matching&quot;">​</a></h3><p>Ensure you keep all <code>&lt;1&gt;</code>, <code>&lt;/1&gt;</code> tags in exactly the same positions.</p><h3 id="source-files-not-found-on-re-export" tabindex="-1">Source files not found on re-export <a class="header-anchor" href="#source-files-not-found-on-re-export" aria-label="Permalink to &quot;Source files not found on re-export&quot;">​</a></h3><p>If you moved your project, use <strong>File → Relocate Source Folder</strong> to point to the new location of the SDLPPX.</p><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./overview.html">CAT Tool Overview</a></li><li><a href="./../import-export/formats.html">Import/Export Formats</a></li></ul>`,46)]))}const g=e(s,[["render",l]]);export{h as __pageData,g as default};
